// Terrain ground textures, cropped from the pipo-map001 tileset.
//
// forest/mountain/snow had partially-transparent corner pixels in the
// source crop (the tileset draws those as rounded organic shapes, not
// full squares) which rendered as solid BLACK on the ground-plane tiles
// (no transparent:true there, so alpha was ignored and raw - black - RGB
// showed through). Fixed by flattening those three onto a matching opaque
// backing color at crop time, so every ground texture here is fully opaque.
//
// TWO representations of the same 8 images are exported here because they
// feed two different consumers with different needs:
//
//  - TERRAIN_TEXTURE (PNG data URIs): used by ColorTerrainMap.js (the 2D
//    map) as the 'uri' for a normal React Native <Image> component, which
//    decodes data-URI PNGs natively - no problem there.
//
//  - TERRAIN_TEXTURE_RAW (raw RGBA pixel bytes): used by RoadmapWorld3D.js
//    (the 3D view) to build a THREE.DataTexture directly. THREE.TextureLoader
//    needs a browser Image element ('document'), which doesn't exist in this
//    bare expo-gl/Hermes environment, so the 3D view cannot use the PNG form -
//    it needs already-decoded pixels. Each entry is { width, height, base64 }
//    where base64 decodes to width*height*4 bytes, RGBA, row-major, top row
//    first. Decode with base64ToUint8Array from base64Decode.js.
//
// deep_water, snow, and shore have no dedicated tile in the sheet, so those
// three are tinted variants of water/mountain/sand; everything else is a
// direct crop.

export const TERRAIN_TEXTURE = {
  grass: 'data:image/png;base64,',
  forest: 'data:image/png;base64,',
  sand: 'data:image/png;base64,',
  shore: 'data:image/png;base64,',
  water: 'data:image/png;base64,',
  deep_water: 'data:image/png;base64,',
  mountain: 'data:image/png;base64,',
  snow: 'data:image/png;base64,',
};

export const TERRAIN_TEXTURE_RAW = {
  grass: { width: 96, height: 96, base64: '' },
  forest: { width: 96, height: 96, base64: '' },
  sand: { width: 96, height: 96, base64: '' },
  shore: { width: 96, height: 96, base64: '' },
  water: { width: 96, height: 96, base64: '' },
  deep_water: { width: 96, height: 96, base64: '' },
  mountain: { width: 96, height: 96, base64: '' },
  snow: { width: 96, height: 96, base64: '' },
};
